(762672, 83557, 21362, '<td valign="top">Great shot. Hope you didn''t really have to be pulled over to get the opportunity for this! ;)</td>', 'Great shot. Hope you didn''t really have to be pulled over to get the opportunity for this! ;)', '2004-06-14 12:25:06.000000', NULL, 1),
(762733, 83590, 4411, '<td valign="top">Technically well done, and  the reflection was a neat idea, but the background is way too hectic and distracting.  Looks to me like the best way to shoot this subject is from lower down, with just the sky as a backdrop.</td>', 'Technically well done, and  the reflection was a neat idea, but the background is way too hectic and distracting.  Looks to me like the best way to shoot this subject is from lower down, with just the sky as a backdrop.', '2004-06-14 13:26:08.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(762737, 82368, 4411, '<td valign="top">Nicely done, and very good composition. Lacking the wow factor though, probably because of the way the white &amp; red of the carriages have merged together to create a faded paintwork effect.</td>', 'Nicely done, and very good composition. Lacking the wow factor though, probably because of the way the white & red of the carriages have merged together to create a faded paintwork effect.', '2004-06-14 13:28:35.000000', NULL, 1),
(762739, 83354, 4411, '<td valign="top">Well that''s different! Nicely composed but let down by the weather. A sunnier day would have made the greens &amp; reds pop very nicely.</td>', 'Well that''s different! Nicely composed but let down by the weather. A sunnier day would have made the greens & reds pop very nicely.', '2004-06-14 13:31:40.000000', NULL, 1),
(762745, 83434, 4411, '<td valign="top">My only major complaint is that you''ve chopped the wheels off. Great idea though : )</td>', 'My only major complaint is that you''ve chopped the wheels off. Great idea though : )', '2004-06-14 13:36:45.000000', NULL, 1),
(762780, 83612, 20235, '<td valign="top">I like the texture and detail on the surface of your subject. This also has a very nostalgic feel to it. The picture seems a tad dark though, but I''m not sure brightening it would really add to it anyways. Nice shot.</td>', 'I like the texture and detail on the surface of your subject. This also has a very nostalgic feel to it. The picture seems a tad dark though, but I''m not sure brightening it would really add to it anyways. Nice shot.', '2004-06-14 14:17:57.000000', NULL, 1),
(762782, 83120, 20235, '<td valign="top">NIce picture. I like the composition and focus here. But imho I don''t think the b&amp;w is working. There is very little contrast between the roof of the engine against the wall.</td>', 'NIce picture. I like the composition and focus here. But imho I don''t think the b&w is working. There is very little contrast between the roof of the engine against the wall.', '2004-06-14 14:19:37.000000', NULL, 1),
(762786, 83476, 20235, '<td valign="top">Good composition and subject. The viewers eye is naturally draw from the man, to along the length of the train. Colors seem a little washed out from the bright sunlight though.</td>', 'Good composition and subject. The viewers eye is naturally draw from the man, to along the length of the train. Colors seem a little washed out from the bright sunlight though.', '2004-06-14 14:21:10.000000', NULL, 1),
