(763126, 83602, 327, '<td valign="top">Not really seeing a plane, train or auto here. Your focus, color are good, but the composition is weak for this challenge.</td>', 'Not really seeing a plane, train or auto here. Your focus, color are good, but the composition is weak for this challenge.', '2004-06-14 18:34:11.000000', NULL, 1),
(763127, 83557, 4159, '<td valign="top">Funny, and well-executed.</td>', 'Funny, and well-executed.', '2004-06-14 18:34:24.000000', NULL, 1),
