(763445, 83594, 20662, '<td valign="top">too bad you can''t submit this to the desaturation challenge as well. Nicely done.</td>', 'too bad you can''t submit this to the desaturation challenge as well. Nicely done.', '2004-06-15 00:31:25.000000', NULL, 1),
(763446, 82222, 20662, '<td valign="top">I''m not sure I like the tree -- it looks like it''s coming out of the passanger seat.</td>', 'I''m not sure I like the tree -- it looks like it''s coming out of the passanger seat.', '2004-06-15 00:34:04.000000', NULL, 1),
(763449, 83558, 20662, '<td valign="top">Wish I could read the banner a little better.</td>', 'Wish I could read the banner a little better.', '2004-06-15 00:36:53.000000', NULL, 1),
(763457, 83577, 20662, '<td valign="top">Would liked to have seen the dog in focus. Since he looks like he''s got a smile on his face it would have made it look like he was in charge.</td>', 'Would liked to have seen the dog in focus. Since he looks like he''s got a smile on his face it would have made it look like he was in charge.', '2004-06-15 00:48:54.000000', NULL, 1),
(763462, 83523, 20662, '<td valign="top">The gradation of the upper sides is a bit distracting otherwise -- a nice photo,</td>', 'The gradation of the upper sides is a bit distracting otherwise -- a nice photo,', '2004-06-15 00:59:49.000000', NULL, 1),
(763474, 83349, 12160, '<td valign="top">Great idea, love it. I like the slow shutter effect.</td>', 'Great idea, love it. I like the slow shutter effect.', '2004-06-15 01:24:01.000000', NULL, 1),
(763476, 82723, 12160, '<td valign="top">The saturated colors really make a statement. Well done. 8</td>', 'The saturated colors really make a statement. Well done. 8', '2004-06-15 01:25:50.000000', NULL, 1),
(763477, 83426, 17233, '<td valign="top">Beautiful shot - great old-time feeling with the high contrast and vignetting.</td>', 'Beautiful shot - great old-time feeling with the high contrast and vignetting.', '2004-06-15 01:26:52.000000', NULL, 1),
(763478, 82734, 17233, '<td valign="top">Great shot - beautifully processed to highlight the form in what could easily have been an otherwise flat image. Good contrast.</td>', 'Great shot - beautifully processed to highlight the form in what could easily have been an otherwise flat image. Good contrast.', '2004-06-15 01:29:54.000000', NULL, 1),
(763480, 83487, 12160, '<td valign="top">Nice shot. Love the candidness of it. The crop really works. The bright sun high in the sky wasn''t a disadvantage in the photo. 8</td>', 'Nice shot. Love the candidness of it. The crop really works. The bright sun high in the sky wasn''t a disadvantage in the photo. 8', '2004-06-15 01:30:43.000000', NULL, 1),
