(763533, 83439, 1009, '<td valign="top">Good job on a fun picture...</td>', 'Good job on a fun picture...', '2004-06-15 03:05:23.000000', NULL, 1),
(763534, 83600, 1009, '<td valign="top">This is a unique and cool shot... good job on the capture. I like the framing and everything.</td>', 'This is a unique and cool shot... good job on the capture. I like the framing and everything.', '2004-06-15 03:06:08.000000', NULL, 1),
(763535, 83442, 1009, '<td valign="top">The contrast, texture, and shadows of this one are awesome! Great job. I hope it goes to the Top 20.</td>', 'The contrast, texture, and shadows of this one are awesome! Great job. I hope it goes to the Top 20.', '2004-06-15 03:06:50.000000', NULL, 1),
(763537, 83139, 1009, '<td valign="top">Nice capture but I don''t find it exciting. I do like the angle though and the framing... maybe I''d like it better if it was brighter. Good job overall...</td>', 'Nice capture but I don''t find it exciting. I do like the angle though and the framing... maybe I''d like it better if it was brighter. Good job overall...', '2004-06-15 03:07:44.000000', NULL, 1),
