(763562, 83442, 10170, '<td valign="top">Excellent.  Lighting works well, and this is nicely off-beat but still fits the challenge beautifully.  Love it.</td>', 'Excellent.  Lighting works well, and this is nicely off-beat but still fits the challenge beautifully.  Love it.', '2004-06-15 04:18:38.000000', NULL, 1),
(763592, 83575, 18326, '<td valign="top">I love the way my eyes were focused on the engine right away</td>', 'I love the way my eyes were focused on the engine right away', '2004-06-15 05:40:50.000000', NULL, 1),
(763602, 83536, 8682, '<td valign="top">wow... fantastic shot. One of my favs of this week. I really love the choice of duotone. Lovely image!</td>', 'wow... fantastic shot. One of my favs of this week. I really love the choice of duotone. Lovely image!', '2004-06-15 05:58:11.000000', NULL, 1),
(763603, 83549, 8682, '<td valign="top">Good picture. 7</td>', 'Good picture. 7', '2004-06-15 05:59:55.000000', NULL, 1),
