(763641, 83594, 16636, '<td valign="top">a nice ''de-sat'' job!!!</td>', 'a nice ''de-sat'' job!!!', '2004-06-15 08:13:45.000000', NULL, 1),
(763645, 83066, 14614, '<td valign="top">I really like your red accents against the high key effect of the city.  Person adds interest to the shot,  you''ve captured a sense of wild motion.  Only wish the white thing in the lower center wasn''t so distracting.  As presented, one of my favorites this challenge -- good luck</td>', 'I really like your red accents against the high key effect of the city.  Person adds interest to the shot,  you''ve captured a sense of wild motion.  Only wish the white thing in the lower center wasn''t so distracting.  As presented, one of my favorites this challenge -- good luck', '2004-06-15 08:34:04.000000', NULL, 1),
(763646, 82995, 14614, '<td valign="top">you''ve captured a great moment.  wish the groom had a bit more light on his face. as presented, one of my favorites this challenge</td>', 'you''ve captured a great moment.  wish the groom had a bit more light on his face. as presented, one of my favorites this challenge', '2004-06-15 08:34:55.000000', NULL, 1),
(763647, 83487, 14614, '<td valign="top">fine shot -- one of my ribbon picks (border detracts a bit - could be smaller)</td>', 'fine shot -- one of my ribbon picks (border detracts a bit - could be smaller)', '2004-06-15 08:35:37.000000', NULL, 1),
(763648, 83599, 14614, '<td valign="top">excellent colors and compostition - one of my ribbon picks!</td>', 'excellent colors and compostition - one of my ribbon picks!', '2004-06-15 08:36:04.000000', NULL, 1),
(763649, 82734, 14614, '<td valign="top">iteresting composition and hi key effect.</td>', 'iteresting composition and hi key effect.', '2004-06-15 08:37:11.000000', NULL, 1),
(763650, 83495, 14614, '<td valign="top">this one has a creepy feel, great color work, (would be excellent if the car was a bit more unusual or interesting - no insult to your car meant!)  light from behind and the streaking cars going by makes the shot.  One of my favorites this challenge</td>', 'this one has a creepy feel, great color work, (would be excellent if the car was a bit more unusual or interesting - no insult to your car meant!)  light from behind and the streaking cars going by makes the shot.  One of my favorites this challenge', '2004-06-15 08:39:20.000000', NULL, 1),
(763701, 83301, 5728, '<td valign="top">And speeding is what mista Trulli does best! Stunning shot, did you have ear plugs in? Those Formula one races are so loud!</td>', 'And speeding is what mista Trulli does best! Stunning shot, did you have ear plugs in? Those Formula one races are so loud!', '2004-06-15 09:51:22.000000', NULL, 1),
(763727, 83473, 6130, '<td valign="top">I like it.</td>', 'I like it.', '2004-06-15 10:18:35.000000', NULL, 1),
(763798, 82510, 16301, '<td valign="top">All I see is the number 7, there is nothing to capture my interest like a plane, train or an automobile in this photo. I know you''re in a car, but its still too vague.</td>', 'All I see is the number 7, there is nothing to capture my interest like a plane, train or an automobile in this photo. I know you''re in a car, but its still too vague.', '2004-06-15 11:24:34.000000', NULL, 1),
(763799, 83596, 16301, '<td valign="top">An off-centered composition might have worked better here.</td>', 'An off-centered composition might have worked better here.', '2004-06-15 11:25:07.000000', NULL, 1),
