(764220, 82222, 18517, '<td valign="top">Mmmm... tastes like pretty. Excellent shot!</td>', 'Mmmm... tastes like pretty. Excellent shot!', '2004-06-15 17:14:12.000000', NULL, 1),
(764221, 82751, 18517, '<td valign="top">The sky never looked so... indecisive! Good shot.</td>', 'The sky never looked so... indecisive! Good shot.', '2004-06-15 17:14:51.000000', NULL, 1),
