(764226, 83567, 18517, '<td valign="top">Oh! God! The world is spinning out of control! Hehe--I think you missed a spot under the car.</td>', 'Oh! God! The world is spinning out of control! Hehe--I think you missed a spot under the car.', '2004-06-15 17:17:31.000000', NULL, 1),
