INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(764236, 82809, 16106, '<td valign="top">pick of the litter. Great geometry and strong use of color allow this composition to shine.</td>', 'pick of the litter. Great geometry and strong use of color allow this composition to shine.', '2004-06-15 17:25:00.000000', NULL, 1),
(764239, 83429, 11895, '<td valign="top">ah, the Concorde, nice shot</td>', 'ah, the Concorde, nice shot', '2004-06-15 17:25:58.000000', NULL, 1),
(764241, 83599, 18517, '<td valign="top">Maybe a little too bright. Very cool.</td>', 'Maybe a little too bright. Very cool.', '2004-06-15 17:27:15.000000', NULL, 1),
(764242, 83434, 16106, '<td valign="top">Very funny shot, well posed and composed Great work on the expression of the model while perching on that tire. A bit more light filling in the front of the van and the model would have helped balance out the strong back light. Top 3</td>', 'Very funny shot, well posed and composed Great work on the expression of the model while perching on that tire. A bit more light filling in the front of the van and the model would have helped balance out the strong back light. Top 3', '2004-06-15 17:27:36.000000', NULL, 1),
(764243, 83284, 18517, '<td valign="top">I don''t get it.</td>', 'I don''t get it.', '2004-06-15 17:29:06.000000', NULL, 1),
(764247, 83518, 18517, '<td valign="top">That''s a car alright!</td>', 'That''s a car alright!', '2004-06-15 17:34:20.000000', NULL, 1),
(764252, 83523, 11895, '<td valign="top">I really like this but it would have looked better if you had cleaned up the upper corners with clone, or cropping</td>', 'I really like this but it would have looked better if you had cleaned up the upper corners with clone, or cropping', '2004-06-15 17:38:11.000000', NULL, 1),
(764253, 83572, 18517, '<td valign="top">Deja Vu. Cool shot.</td>', 'Deja Vu. Cool shot.', '2004-06-15 17:38:28.000000', NULL, 1),
(764258, 83429, 11518, '<td valign="top">Great shot, 9</td>', 'Great shot, 9', '2004-06-15 17:47:01.000000', NULL, 1),
(764263, 83594, 16004, '<td valign="top">this is an intriguing picture.  with the possession of buses (including the lame one at the back) they have the appearance of a (albeit wagon) train.  nice practice for the selective desat challenge too.  focus is nicely maintained, but i would have cropped it differently - there''s too much empty road in the foreground which isn''t countered by any emptiness at the top.  it''s also a little bit on the pale / bright side, but that''s more personal taste and isn''t a problem vote-wise.  7.</td>', 'this is an intriguing picture.  with the possession of buses (including the lame one at the back) they have the appearance of a (albeit wagon) train.  nice practice for the selective desat challenge too.  focus is nicely maintained, but i would have cropped it differently - there''s too much empty road in the foreground which isn''t countered by any emptiness at the top.  it''s also a little bit on the pale / bright side, but that''s more personal taste and isn''t a problem vote-wise.  7.', '2004-06-15 18:04:06.000000', NULL, 1),
(764265, 83209, 19751, '<td valign="top">At first I thought this was a Doppler on Wheels... but I definitely still appreciate it :-) However, the lighting could be better(on the vehicles) but the quality and focus of the picture is very nice.</td>', 'At first I thought this was a Doppler on Wheels... but I definitely still appreciate it :-) However, the lighting could be better(on the vehicles) but the quality and focus of the picture is very nice.', '2004-06-15 18:04:52.000000', NULL, 1),
(764266, 83584, 19751, '<td valign="top">The picture is a little grainy/oversharpened and the lighting is too bright. Try taking the same picture a few hours later in the day and it would look much better.</td>', 'The picture is a little grainy/oversharpened and the lighting is too bright. Try taking the same picture a few hours later in the day and it would look much better.', '2004-06-15 18:06:09.000000', NULL, 1),
(764268, 82494, 16004, '<td valign="top">blimey, that guy looks like he has the wrath of a thousand volcanoes, and directed right at YOU!  i am in awe of your ability to take such a picture in front of everyone.  were you brave enough to come up with the camera and look through the lens, or did you nonchalantly stretch your arms and click?  the shot is a little unsharp, but the colours, people, angle and FEEL of the picture more than make up for that.  i would have been tempted to clone out the girls head though - she has too much movement going on there.  i love the blue light outside.  7.</td>', 'blimey, that guy looks like he has the wrath of a thousand volcanoes, and directed right at YOU!  i am in awe of your ability to take such a picture in front of everyone.  were you brave enough to come up with the camera and look through the lens, or did you nonchalantly stretch your arms and click?  the shot is a little unsharp, but the colours, people, angle and FEEL of the picture more than make up for that.  i would have been tempted to clone out the girls head though - she has too much movement going on there.  i love the blue light outside.  7.', '2004-06-15 18:07:45.000000', NULL, 1),
(764269, 83429, 19751, '<td valign="top">Great sky for the top half of the picture... not so great for the bottom half. This can''t really be helped. Very nice idea. The only thing that seems to be hindering this picture is the sky on te bottom half because the plane kind of blends into it. Great job</td>', 'Great sky for the top half of the picture... not so great for the bottom half. This can''t really be helped. Very nice idea. The only thing that seems to be hindering this picture is the sky on te bottom half because the plane kind of blends into it. Great job', '2004-06-15 18:07:57.000000', NULL, 1),
(764270, 83483, 19751, '<td valign="top">hahaa... very funny</td>', 'hahaa... very funny', '2004-06-15 18:09:00.000000', NULL, 1),
(764272, 83452, 19751, '<td valign="top">Strange lighting on the smoke and plane. Gives it an eerie effect</td>', 'Strange lighting on the smoke and plane. Gives it an eerie effect', '2004-06-15 18:10:40.000000', NULL, 1),
(764273, 83497, 16004, '<td valign="top">excellent.  the sky is great, the white body of the plane very defined, the heat wobbleness (technical term escapes me) dramatic (proves to me its not a model on a cloned-out stick), slightly obscure taste in airline (apologies if that''s offending).  minor suggestion would be to clone out the little white square on the pole; makes it look like the aircraft is going to touch down on a golf course.  a favourite of the airplane shots - 9.</td>', 'excellent.  the sky is great, the white body of the plane very defined, the heat wobbleness (technical term escapes me) dramatic (proves to me its not a model on a cloned-out stick), slightly obscure taste in airline (apologies if that''s offending).  minor suggestion would be to clone out the little white square on the pole; makes it look like the aircraft is going to touch down on a golf course.  a favourite of the airplane shots - 9.', '2004-06-15 18:11:10.000000', NULL, 1),
(764275, 83066, 19751, '<td valign="top">I like this picture. The sky and buildings are almost too white for my liking, but that is what you intended. I would love to know how you did it.</td>', 'I like this picture. The sky and buildings are almost too white for my liking, but that is what you intended. I would love to know how you did it.', '2004-06-15 18:13:51.000000', NULL, 1),
(764276, 83475, 19751, '<td valign="top">oooo if only the sky was better! this is a great picture. it gives the feel of a plane about to land on your head. I like the little storm though. hehe</td>', 'oooo if only the sky was better! this is a great picture. it gives the feel of a plane about to land on your head. I like the little storm though. hehe', '2004-06-15 18:14:45.000000', NULL, 1),
(764277, 83379, 16004, '<td valign="top">you hid in the bushes to take a picture of a 1998 Mondeo?  i like the shades applied to the image, and you''re capture of a moving object is very good. i also very much like the composition, highlight being the grasses in the foreground.  i''m not overly keen on the choice of car (it''s worth hanging on for something a bit more unqiue), the dog poo shaped thing in the road is a bit of a distraction, and the way it''s cropped with the car only in the top half of the image, though different and original, gives it a slight unbalanced appearance.  5.</td>', 'you hid in the bushes to take a picture of a 1998 Mondeo?  i like the shades applied to the image, and you''re capture of a moving object is very good. i also very much like the composition, highlight being the grasses in the foreground.  i''m not overly keen on the choice of car (it''s worth hanging on for something a bit more unqiue), the dog poo shaped thing in the road is a bit of a distraction, and the way it''s cropped with the car only in the top half of the image, though different and original, gives it a slight unbalanced appearance.  5.', '2004-06-15 18:16:38.000000', NULL, 1),
(764281, 83479, 19751, '<td valign="top">I dont really like the reflections in the windows.. but when you''re taking an outside picture, that is very hard to get rid of. If this picture was taken out where there wasnt a house or another car in the background, i think it would do much better</td>', 'I dont really like the reflections in the windows.. but when you''re taking an outside picture, that is very hard to get rid of. If this picture was taken out where there wasnt a house or another car in the background, i think it would do much better', '2004-06-15 18:20:48.000000', NULL, 1),
(764283, 83523, 19751, '<td valign="top">I like the feel this one gives. Great job</td>', 'I like the feel this one gives. Great job', '2004-06-15 18:21:28.000000', NULL, 1),
(764284, 83434, 16004, '<td valign="top">this is a good one.  the whole hippy thing with the jet flying over is inspired - what on earth made you conjure this up in your head is intriguing.  the lighting is very striking, though it''s a pity you weren''t a little more to the left to give the minibus a less straight on profile.  9.</td>', 'this is a good one.  the whole hippy thing with the jet flying over is inspired - what on earth made you conjure this up in your head is intriguing.  the lighting is very striking, though it''s a pity you weren''t a little more to the left to give the minibus a less straight on profile.  9.', '2004-06-15 18:21:37.000000', NULL, 1),
(764285, 83450, 19751, '<td valign="top">This is one of my favorites of this challenge. Great Composition</td>', 'This is one of my favorites of this challenge. Great Composition', '2004-06-15 18:22:26.000000', NULL, 1),
(764286, 82256, 19751, '<td valign="top">definitely fits the challenge, but it would loook much better if taken later in the day when the sky wasn''t white, or with proper use of a polarizing filter.</td>', 'definitely fits the challenge, but it would loook much better if taken later in the day when the sky wasn''t white, or with proper use of a polarizing filter.', '2004-06-15 18:23:14.000000', NULL, 1),
(764289, 83473, 16004, '<td valign="top">wow - this shot is just so period!  i love cars of this era, and you''ve captured it perfectly - having the owner in the shot is just the proverbial cherry.  i can almost smell the old thing (car, not guy).  looks similar to a car dad had, so a bit of sentimentality is going to cloud my judgment.  9.</td>', 'wow - this shot is just so period!  i love cars of this era, and you''ve captured it perfectly - having the owner in the shot is just the proverbial cherry.  i can almost smell the old thing (car, not guy).  looks similar to a car dad had, so a bit of sentimentality is going to cloud my judgment.  9.', '2004-06-15 18:24:11.000000', NULL, 1),
(764290, 83372, 19751, '<td valign="top">This looks more like a picture of a kid rather than of a mode of transportation. The shadows in the pic are long, so I assume it is somewhat late in the day... but waiting a little bit longer might help the overall color</td>', 'This looks more like a picture of a kid rather than of a mode of transportation. The shadows in the pic are long, so I assume it is somewhat late in the day... but waiting a little bit longer might help the overall color', '2004-06-15 18:24:56.000000', NULL, 1),
(764293, 83166, 16004, '<td valign="top">unlucky on the timing front - did you just miss it landing?  the majoy problem i have with this is that the helicopter is not prominent or even obvious enough in the image - it''s far too hidden and the eyes are drawn to the steel posts supporting the helipad.  i would have possibly cropped out the fence at the bottom and the tree on the left (these are distracting, more so as they''re the only bits not in focus).  the sky, a nice blue, is good and should fill the image more...   it has promise - if only you arrived a few minutes earlier...</td>', 'unlucky on the timing front - did you just miss it landing?  the majoy problem i have with this is that the helicopter is not prominent or even obvious enough in the image - it''s far too hidden and the eyes are drawn to the steel posts supporting the helipad.  i would have possibly cropped out the fence at the bottom and the tree on the left (these are distracting, more so as they''re the only bits not in focus).  the sky, a nice blue, is good and should fill the image more...   it has promise - if only you arrived a few minutes earlier...', '2004-06-15 18:27:54.000000', NULL, 1),
(764295, 83479, 18191, '<td valign="top">I think that the angle could have been more interesting.</td>', 'I think that the angle could have been more interesting.', '2004-06-15 18:32:14.000000', NULL, 1),
(764299, 83284, 16004, '<td valign="top">Firstly, i have no idea what''s happening with the aircraft, or what is being conveyed by the wobbliness.  Secondly, the wind sock is far too prominent and is diverting ones  attention from the plane.  and thirdly, not wanting to sound too hurtful, but i think the title is bordering on upsetting.</td>', 'Firstly, i have no idea what''s happening with the aircraft, or what is being conveyed by the wobbliness.  Secondly, the wind sock is far too prominent and is diverting ones  attention from the plane.  and thirdly, not wanting to sound too hurtful, but i think the title is bordering on upsetting.', '2004-06-15 18:34:55.000000', NULL, 1),
(764302, 83614, 19751, '<td valign="top">i like the composition, but the lighting almost washes out the color in the dirt and the planes.</td>', 'i like the composition, but the lighting almost washes out the color in the dirt and the planes.', '2004-06-15 18:37:16.000000', NULL, 1),
(764304, 83601, 19751, '<td valign="top">great angle on the plane and great positioning. Not the best quality though... but nice</td>', 'great angle on the plane and great positioning. Not the best quality though... but nice', '2004-06-15 18:38:54.000000', NULL, 1),
(764308, 83564, 11895, '<td valign="top">good idea but the sky and clouds look overly edited and unnatural</td>', 'good idea but the sky and clouds look overly edited and unnatural', '2004-06-15 18:44:59.000000', NULL, 1),
(764312, 83066, 16004, '<td valign="top">i like this.  the white-out effect is very good, having the natwest tower in full frame is ALWAYS a good thing, and what i like best is the girl on the island, still amongst all the blurriness.  i''m having fun trying to guess where this is - it''s west of the tower perhaps...   bank looking up threadneedle?  only think is, it''s a shame the buses in the background are clearly defined.  but that''s the only thing</td>', 'i like this.  the white-out effect is very good, having the natwest tower in full frame is ALWAYS a good thing, and what i like best is the girl on the island, still amongst all the blurriness.  i''m having fun trying to guess where this is - it''s west of the tower perhaps...   bank looking up threadneedle?  only think is, it''s a shame the buses in the background are clearly defined.  but that''s the only thing', '2004-06-15 18:47:41.000000', NULL, 1),
(764339, 83050, 19751, '<td valign="top">one of my favorites in the challenge. I hope you ribbon or at least be one of the tops!  great job!</td>', 'one of my favorites in the challenge. I hope you ribbon or at least be one of the tops!  great job!', '2004-06-15 19:17:17.000000', NULL, 1),
(764352, 83567, 22781, '<td valign="top">The motion blur could be a bit better, then also dont forget the weels.</td>', 'The motion blur could be a bit better, then also dont forget the weels.', '2004-06-15 19:32:54.000000', NULL, 1),
(764354, 83491, 22781, '<td valign="top">I like the angle.... 8</td>', 'I like the angle.... 8', '2004-06-15 19:33:39.000000', NULL, 1),
(764356, 83598, 22781, '<td valign="top">I got it :)</td>', 'I got it :)', '2004-06-15 19:37:06.000000', NULL, 1),
(764363, 83539, 22781, '<td valign="top">Central station Amsterdam I guess?<br/>I''ve never seen it like this before! Great shot! <br/>1 of my 2 10''s in this competition, hope you win!</td>', 'Central station Amsterdam I guess?I''ve never seen it like this before! Great shot! 1 of my 2 10''s in this competition, hope you win!', '2004-06-15 19:43:54.000000', NULL, 1),
