(764451, 83354, 6405, '<td valign="top">That is a nice use,I know some people who can use their cameras for that purpose ! :-)<br/>8</td>', 'That is a nice use,I know some people who can use their cameras for that purpose ! :-)8', '2004-06-15 21:03:47.000000', NULL, 1),
