(766486, 82510, 22781, '<td valign="top">I can''t make out anything. Sorry for this, but I am being honest. I''m not a good photographer myself, but had to give this a 2</td>', 'I can''t make out anything. Sorry for this, but I am being honest. I''m not a good photographer myself, but had to give this a 2', '2004-06-16 18:14:41.000000', NULL, 1),
(766494, 83066, 20941, '<td valign="top">artistic composition and editing, i like it</td>', 'artistic composition and editing, i like it', '2004-06-16 18:16:49.000000', NULL, 1),
(766496, 83555, 20941, '<td valign="top">way cool!</td>', 'way cool!', '2004-06-16 18:18:11.000000', NULL, 1),
(766559, 83587, 3765, '<td valign="top">Clever exposure and composition. 8</td>', 'Clever exposure and composition. 8', '2004-06-16 18:33:37.000000', NULL, 1),
