(769883, 83450, 1009, '<td valign="top">Nice shot, the train seems very reflective, is it polished??? Nice sky, nice POV, the conductor leaning off the side really adds to this shot for me... good job.</td>', 'Nice shot, the train seems very reflective, is it polished??? Nice sky, nice POV, the conductor leaning off the side really adds to this shot for me... good job.', '2004-06-20 06:44:54.000000', NULL, 1),
(769884, 83134, 1009, '<td valign="top">Careful, mind the gap. Interesting shot but the train is lost in the distance. I would have liked to see this one entered in the "edges" challenge. As it is, good job.</td>', 'Careful, mind the gap. Interesting shot but the train is lost in the distance. I would have liked to see this one entered in the "edges" challenge. As it is, good job.', '2004-06-20 06:46:19.000000', NULL, 1),
