(769898, 83210, 1009, '<td valign="top">Nice shot, I love the yellow effect. The framing and POV is great too. Good job.</td>', 'Nice shot, I love the yellow effect. The framing and POV is great too. Good job.', '2004-06-20 06:51:51.000000', NULL, 1),
(769899, 83491, 1009, '<td valign="top">Nice shot. I like the contrast, POV, and the red door is great! Would have been a nice shot for the "selective desaturation" challenge! Good job...</td>', 'Nice shot. I like the contrast, POV, and the red door is great! Would have been a nice shot for the "selective desaturation" challenge! Good job...', '2004-06-20 06:53:10.000000', NULL, 1),
(769900, 83521, 1009, '<td valign="top">Man am I ever glad I moved out of LA, this is one part of life that I won''t miss. Sometimes its hard to believe that I wasted 4 hours of my life everyday doing this...</td>', 'Man am I ever glad I moved out of LA, this is one part of life that I won''t miss. Sometimes its hard to believe that I wasted 4 hours of my life everyday doing this...', '2004-06-20 06:54:53.000000', NULL, 1),
