(769908, 83525, 1009, '<td valign="top">Nice shot, but it doesn''t have much excitement for me. I do really like the color saturation though, awesome.</td>', 'Nice shot, but it doesn''t have much excitement for me. I do really like the color saturation though, awesome.', '2004-06-20 06:58:45.000000', NULL, 1),
(769910, 83509, 1009, '<td valign="top">This is a cool shot. Looks like something you''d see in a car commercial. I like the POV, the contrast, and the bright blue sky. Good job...</td>', 'This is a cool shot. Looks like something you''d see in a car commercial. I like the POV, the contrast, and the bright blue sky. Good job...', '2004-06-20 06:59:21.000000', NULL, 1),
